--08600 relationship-bound source; no provider execution or activation.
BEGIN;
DO $guard$
DECLARE context_source text; consumer_source text;
BEGIN
 SELECT prosrc INTO context_source FROM pg_proc WHERE oid='public.sandy_provider_supplement_context(jsonb)'::regprocedure AND prosecdef;
 SELECT prosrc INTO consumer_source FROM pg_proc WHERE oid='public.sandy_credential_resolve_consumer(text,uuid,uuid,text)'::regprocedure AND prosecdef;
 IF encode(extensions.digest(context_source,'sha256'),'hex') IS DISTINCT FROM '696fbb31a0cee684185831b25d94b732cc1b94364a8033f8beb541d8d185d826' OR encode(extensions.digest(consumer_source,'sha256'),'hex') IS DISTINCT FROM '21f935d53ca429c9a884f40707eb661acf1754c0ea9343e248e874573e962f60' THEN RAISE EXCEPTION 'reviewed08500_private_boundary_required'; END IF;
END $guard$;
CREATE OR REPLACE FUNCTION public.sandy_provider_supplement_context(p_context jsonb) RETURNS public.sandy_api_execution_admissions LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS '
DECLARE admission public.sandy_api_execution_admissions; entry public.sandy_operation_registry; target text;
BEGIN
 IF jsonb_typeof(p_context) IS DISTINCT FROM ''object''
 OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_context) key WHERE key NOT IN
 (''actor'',''admission'',''operation'',''scope_sha256'',''input_sha256'',''binding_sha256'',''target'',''kind'',''payload_base64'',''payload_sha256'',''byte_length'',''media_type''))
 OR p_context->>''actor'' IS NULL OR p_context->>''admission'' IS NULL
 OR p_context->>''operation'' !~ ''^(gcp|supabase|github)\.[a-z][a-z0-9_.-]{1,95}$''
 OR p_context->>''scope_sha256'' !~ ''^[a-f0-9]{64}$'' OR p_context->>''input_sha256'' !~ ''^[a-f0-9]{64}$''
 OR p_context->>''binding_sha256'' !~ ''^[a-f0-9]{64}$''
 OR p_context->>''kind'' NOT IN (''cursor'',''artifact'',''redirect'') THEN RAISE EXCEPTION ''supplement_context_invalid''; END IF;
 SELECT * INTO admission FROM public.sandy_api_execution_admissions WHERE id=(p_context->>''admission'')::uuid FOR SHARE;
 IF admission.id IS NULL OR admission.actor_id IS DISTINCT FROM (p_context->>''actor'')::uuid
 OR admission.tenant_id IS NOT NULL OR admission.credential_id IS NOT NULL OR admission.approval_id IS NULL
 OR admission.operation IS DISTINCT FROM p_context->>''operation'' OR admission.state IS DISTINCT FROM ''consumed''
 OR admission.scope_sha256 IS DISTINCT FROM p_context->>''scope_sha256'' OR admission.input_sha256 IS DISTINCT FROM p_context->>''input_sha256''
 OR admission.expires_at<=clock_timestamp() OR NOT public.sandy_api_current_owner(admission.actor_id)
 THEN RAISE EXCEPTION ''supplement_consumed_owner_admission_required''; END IF;
 SELECT * INTO entry FROM public.sandy_operation_registry WHERE operation=admission.operation FOR SHARE;
 IF entry.handler IS NULL OR entry.handler NOT IN (''sandy-provider-supplement-api'',''sandy-provider-sensitive-api'',''sandy-provider-bound-api'') OR entry.api_exposed IS DISTINCT FROM true OR entry.verified IS DISTINCT FROM true
 OR entry.error_contract->>''requires_approval'' IS DISTINCT FROM ''true'' OR entry.error_contract->>''api_key_delegable'' IS DISTINCT FROM ''false''
 OR entry.error_contract->>''requires_grant'' IS DISTINCT FROM ''true'' OR entry.permission_scope IS DISTINCT FROM ''infrastructure:write''
 OR entry.is_mutation IS DISTINCT FROM admission.is_mutation
 OR public.sandy_api_registry_revision(admission.operation) IS DISTINCT FROM admission.registry_revision_sha256
 THEN RAISE EXCEPTION ''supplement_current_verified_contract_required''; END IF;
 target:=p_context->>''target'';
 IF target IS NULL OR octet_length(target)>3000 OR target ~ ''[[:cntrl:]]'' OR target ~ ''(%0[aAdD]|[[:space:]#])''
 OR (CASE
 WHEN admission.operation LIKE ''supabase.functions.%'' THEN target !~ ''^https://api\.supabase\.com/v1/projects/zmqlyygzqoidkcwdysok/functions/[a-z][a-z0-9-]{0,62}/body$''
 WHEN admission.operation LIKE ''github.%'' THEN target !~ ''^https://api\.github\.com/repos/ausstyle/web-staging/actions/(jobs|runs|artifacts)/[0-9]+/''
 WHEN admission.operation=''gcp.organizations.search_filtered'' THEN target !~ ''^https://cloudresourcemanager\.googleapis\.com/v3/organizations:search\?pageSize=[0-9]+$''
 WHEN admission.operation=''gcp.folders.search_filtered'' THEN target !~ ''^https://cloudresourcemanager\.googleapis\.com/v3/folders:search\?query=state%3DACTIVE&pageSize=[0-9]+$''
 WHEN admission.operation=''gcp.projects.search_filtered'' THEN target !~ ''^https://cloudresourcemanager\.googleapis\.com/v3/projects:search\?query=projectId%3Aelaborate-haven-511518-a5&pageSize=[0-9]+$''
 WHEN admission.operation=''gcp.projects.list_filtered'' THEN target !~ ''^https://cloudresourcemanager\.googleapis\.com/v3/projects\?parent=(folders|organizations)%2F[0-9]+&pageSize=[0-9]+$''
 WHEN admission.operation=''gcp.billing.accounts.list_filtered'' THEN target !~ ''^https://cloudbilling\.googleapis\.com/v1/billingAccounts\?pageSize=[0-9]+$''
 WHEN admission.operation=''gcp.load_balancers.backends.effective_security_policies.capture'' THEN target !~ ''^https://compute\.googleapis\.com/compute/v1/projects/elaborate-haven-511518-a5/global/backendServices/[a-z][a-z0-9-]{0,62}/getEffectiveSecurityPolicies$''
 WHEN admission.operation=''gcp.artifacts.files.download.capture'' THEN target !~ ''^https://artifactregistry\.googleapis\.com/v1/projects/elaborate-haven-511518-a5/locations/europe-west1/repositories/[a-z][a-z0-9-]{0,62}/files/[^?#]+:download\?alt=media$''
 WHEN admission.operation=''gcp.backup.data_sources.fetch_access_token.capture'' THEN target !~ ''^https://backupdr\.googleapis\.com/v1/projects/elaborate-haven-511518-a5/locations/europe-west1/backupVaults/[A-Za-z0-9_-]{1,200}/dataSources/[A-Za-z0-9_-]{1,200}:fetchAccessToken$''
 WHEN admission.operation=''gcp.compute.instances.get_guest_attributes.capture'' THEN target !~ ''^https://compute\.googleapis\.com/compute/v1/projects/elaborate-haven-511518-a5/zones/europe-west1-b/instances/[a-z](?:[-a-z0-9]{0,61}[a-z0-9])?/getGuestAttributes(?:\?(?:queryPath|variableKey)=[^#[:space:]]*(?:&(?:queryPath|variableKey)=[^#[:space:]]*)*)?$''
 WHEN admission.operation=''gcp.compute.instances.get_screenshot.capture'' THEN target !~ ''^https://compute\.googleapis\.com/compute/v1/projects/elaborate-haven-511518-a5/zones/europe-west1-b/instances/[a-z](?:[-a-z0-9]{0,61}[a-z0-9])?/screenshot$''
 WHEN admission.operation=''gcp.compute.instances.get_shielded_instance_identity.capture'' THEN target !~ ''^https://compute\.googleapis\.com/compute/v1/projects/elaborate-haven-511518-a5/zones/europe-west1-b/instances/[a-z](?:[-a-z0-9]{0,61}[a-z0-9])?/getShieldedInstanceIdentity$''
 WHEN admission.operation=''gcp.kms.crypto_key_versions.asymmetric_decrypt.capture'' THEN target !~ ''^https://cloudkms\.googleapis\.com/v1/projects/elaborate-haven-511518-a5/locations/europe-west1/keyRings/[A-Za-z0-9_-]{1,200}/cryptoKeys/[A-Za-z0-9_-]{1,200}/cryptoKeyVersions/[A-Za-z0-9_-]{1,200}:asymmetricDecrypt$''
 WHEN admission.operation=''gcp.kms.crypto_key_versions.asymmetric_sign.capture'' THEN target !~ ''^https://cloudkms\.googleapis\.com/v1/projects/elaborate-haven-511518-a5/locations/europe-west1/keyRings/[A-Za-z0-9_-]{1,200}/cryptoKeys/[A-Za-z0-9_-]{1,200}/cryptoKeyVersions/[A-Za-z0-9_-]{1,200}:asymmetricSign$''
 WHEN admission.operation=''gcp.kms.crypto_key_versions.decapsulate.capture'' THEN target !~ ''^https://cloudkms\.googleapis\.com/v1/projects/elaborate-haven-511518-a5/locations/europe-west1/keyRings/[A-Za-z0-9_-]{1,200}/cryptoKeys/[A-Za-z0-9_-]{1,200}/cryptoKeyVersions/[A-Za-z0-9_-]{1,200}:decapsulate$''
 WHEN admission.operation=''gcp.kms.crypto_key_versions.export_trusted_key_wrapped_crypto_key_version.capture'' THEN target !~ ''^https://cloudkms\.googleapis\.com/v1/projects/elaborate-haven-511518-a5/locations/europe-west1/keyRings/[A-Za-z0-9_-]{1,200}/cryptoKeys/[A-Za-z0-9_-]{1,200}/cryptoKeyVersions/[A-Za-z0-9_-]{1,200}:exportTrustedKeyWrappedCryptoKeyVersion(?:\?(?:wrappingKey)=[^#[:space:]]*(?:&(?:wrappingKey)=[^#[:space:]]*)*)?$''
 WHEN admission.operation=''gcp.kms.crypto_key_versions.get_public_key.capture'' THEN target !~ ''^https://cloudkms\.googleapis\.com/v1/projects/elaborate-haven-511518-a5/locations/europe-west1/keyRings/[A-Za-z0-9_-]{1,200}/cryptoKeys/[A-Za-z0-9_-]{1,200}/cryptoKeyVersions/[A-Za-z0-9_-]{1,200}/publicKey(?:\?(?:publicKeyFormat)=[^#[:space:]]*(?:&(?:publicKeyFormat)=[^#[:space:]]*)*)?$''
 WHEN admission.operation=''gcp.kms.crypto_key_versions.import_trusted_key_wrapped_crypto_key_version.capture'' THEN target !~ ''^https://cloudkms\.googleapis\.com/v1/projects/elaborate-haven-511518-a5/locations/europe-west1/keyRings/[A-Za-z0-9_-]{1,200}/cryptoKeys/[A-Za-z0-9_-]{1,200}/cryptoKeyVersions:importTrustedKeyWrappedCryptoKeyVersion$''
 WHEN admission.operation=''gcp.kms.crypto_key_versions.mac_sign.capture'' THEN target !~ ''^https://cloudkms\.googleapis\.com/v1/projects/elaborate-haven-511518-a5/locations/europe-west1/keyRings/[A-Za-z0-9_-]{1,200}/cryptoKeys/[A-Za-z0-9_-]{1,200}/cryptoKeyVersions/[A-Za-z0-9_-]{1,200}:macSign$''
 WHEN admission.operation=''gcp.kms.crypto_key_versions.mac_verify.capture'' THEN target !~ ''^https://cloudkms\.googleapis\.com/v1/projects/elaborate-haven-511518-a5/locations/europe-west1/keyRings/[A-Za-z0-9_-]{1,200}/cryptoKeys/[A-Za-z0-9_-]{1,200}/cryptoKeyVersions/[A-Za-z0-9_-]{1,200}:macVerify$''
 WHEN admission.operation=''gcp.kms.crypto_key_versions.raw_decrypt.capture'' THEN target !~ ''^https://cloudkms\.googleapis\.com/v1/projects/elaborate-haven-511518-a5/locations/europe-west1/keyRings/[A-Za-z0-9_-]{1,200}/cryptoKeys/[A-Za-z0-9_-]{1,200}/cryptoKeyVersions/[A-Za-z0-9_-]{1,200}:rawDecrypt$''
 WHEN admission.operation=''gcp.kms.crypto_key_versions.raw_encrypt.capture'' THEN target !~ ''^https://cloudkms\.googleapis\.com/v1/projects/elaborate-haven-511518-a5/locations/europe-west1/keyRings/[A-Za-z0-9_-]{1,200}/cryptoKeys/[A-Za-z0-9_-]{1,200}/cryptoKeyVersions/[A-Za-z0-9_-]{1,200}:rawEncrypt$''
 WHEN admission.operation=''gcp.kms.crypto_keys.decrypt.capture'' THEN target !~ ''^https://cloudkms\.googleapis\.com/v1/projects/elaborate-haven-511518-a5/locations/europe-west1/keyRings/[A-Za-z0-9_-]{1,200}/cryptoKeys/[A-Za-z0-9_-]{1,200}(?:/cryptoKeyVersions/[0-9]{1,20})?:decrypt$''
 WHEN admission.operation=''gcp.kms.crypto_keys.encrypt.capture'' THEN target !~ ''^https://cloudkms\.googleapis\.com/v1/projects/elaborate-haven-511518-a5/locations/europe-west1/keyRings/[A-Za-z0-9_-]{1,200}/cryptoKeys/[A-Za-z0-9_-]{1,200}(?:/cryptoKeyVersions/[0-9]{1,20})?:encrypt$''
 WHEN admission.operation=''gcp.kubernetes.clusters.get_jwks.capture'' THEN target !~ ''^https://container\.googleapis\.com/v1/projects/elaborate-haven-511518-a5/locations/europe-west1/clusters/[A-Za-z0-9_-]{1,200}/jwks$''
 WHEN admission.operation=''gcp.monitoring.notification_channels.get_verification_code.capture'' THEN target !~ ''^https://monitoring\.googleapis\.com/v3/projects/elaborate-haven-511518-a5/notificationChannels/[A-Za-z0-9_-]{1,200}:getVerificationCode$''
 WHEN admission.operation=''supabase.branches.diff.bound'' THEN target !~ ''^https://api\.supabase\.com/v1/branches/([a-z]{20}|[a-fA-F0-9-]{36})/diff(?:\?(?:included_schemas=(?:[A-Za-z0-9*._+-]|%[0-9A-F]{2})*(?:&pgdelta=(?:[A-Za-z0-9*._+-]|%[0-9A-F]{2})*)?|pgdelta=(?:[A-Za-z0-9*._+-]|%[0-9A-F]{2})*))?$''
 WHEN admission.operation=''gcp.firewall_policies.list.bound'' THEN target !~ ''^https://compute\.googleapis\.com/compute/v1/locations/global/firewallPolicies\?(?:[^#[:space:]]*&)?parentId=(folders|organizations)%2F[0-9]+(?:&[^#[:space:]]*)?$''
 WHEN admission.operation=''gcp.pubsub.snapshots.list.bound'' THEN target !~ ''^https://pubsub\.googleapis\.com/v1/projects/elaborate-haven-511518-a5/snapshots\?[^#[:space:]]*$''
 ELSE true END) THEN RAISE EXCEPTION ''supplement_fixed_resource_required''; END IF;
 IF (p_context->>''kind''=''cursor'') IS DISTINCT FROM (admission.operation IN (''gcp.organizations.search_filtered'',''gcp.folders.search_filtered'',''gcp.projects.list_filtered'',''gcp.projects.search_filtered'',''gcp.billing.accounts.list_filtered'',''gcp.firewall_policies.list.bound'',''gcp.pubsub.snapshots.list.bound''))
 OR p_context->>''kind''=''redirect'' AND admission.operation NOT LIKE ''github.actions.%''
 THEN RAISE EXCEPTION ''supplement_payload_kind_refused''; END IF;
 RETURN admission;
END ';
CREATE OR REPLACE FUNCTION public.sandy_credential_resolve_consumer(p_consumer text,p_actor uuid,p_admission uuid,p_operation text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS '
DECLARE admission public.sandy_api_execution_admissions; credential public.sandy_api_credentials;
 entry public.sandy_operation_registry; binding public.sandy_credential_consumer_bindings;
 target public.sandy_credential_targets; version public.sandy_credential_versions; previous public.sandy_credential_consumer_access;
 operation_target public.sandy_credential_targets; expected_consumer text; material text; target_document jsonb;
BEGIN
 IF p_consumer IS NULL OR p_consumer NOT IN (''supabase_management'',''github_api'',''gcp_access_token'')
 OR p_actor IS NULL OR p_admission IS NULL OR p_operation IS NULL OR p_operation !~ ''^[a-z][a-z0-9_.-]{2,100}$'' THEN RAISE EXCEPTION ''consumer_execution_context_invalid''; END IF;
 SELECT * INTO admission FROM public.sandy_api_execution_admissions WHERE id=p_admission FOR SHARE;
 IF admission.id IS NULL OR admission.actor_id IS DISTINCT FROM p_actor OR admission.operation IS DISTINCT FROM p_operation OR admission.state IS DISTINCT FROM ''consumed''
 OR admission.tenant_id IS NOT NULL OR admission.expires_at<=clock_timestamp() OR NOT public.sandy_api_current_owner(p_actor) THEN RAISE EXCEPTION ''consumer_scoped_admission_required''; END IF;
 SELECT * INTO entry FROM public.sandy_operation_registry WHERE operation=p_operation FOR SHARE;
 IF entry.operation IS NULL OR entry.api_exposed IS DISTINCT FROM true OR public.sandy_api_registry_revision(p_operation) IS DISTINCT FROM admission.registry_revision_sha256
 OR entry.handler IS NULL OR entry.handler NOT IN (''sandy-provider-operation-api'',''sandy-credential-lifecycle-api'',''sandy-database-operation-api'',''sandy-guest-operation-api'',''sandy-provider-read-api'',''sandy-provider-gap-api'',''sandy-provider-supplement-api'',''sandy-provider-sensitive-api'',''sandy-provider-bound-api'') THEN RAISE EXCEPTION ''consumer_current_contract_required''; END IF;
 IF admission.credential_id IS NOT NULL THEN
  SELECT * INTO credential FROM public.sandy_api_credentials WHERE id=admission.credential_id FOR SHARE;
  IF credential.id IS NULL OR credential.principal_id IS DISTINCT FROM p_actor OR credential.tenant_id IS NOT NULL OR credential.revoked_at IS NOT NULL OR credential.expires_at<=clock_timestamp()
  OR NOT p_operation=ANY(credential.allowed_operations) OR entry.is_mutation OR entry.error_contract->>''api_key_delegable'' IS DISTINCT FROM ''true'' THEN RAISE EXCEPTION ''consumer_delegated_scope_refused''; END IF;
 END IF;
 -- Original metadata reads have gateway-owned grants. They must first claim
 -- the exact versioned argument context against that actual consumed admission.
 IF entry.handler=''sandy-provider-read-api'' AND (
  admission.is_mutation OR entry.is_mutation OR entry.permission_scope IS DISTINCT FROM ''infrastructure:read''
  OR admission.scope_sha256 IS DISTINCT FROM encode(extensions.digest(''{"permission_scope":"infrastructure:read","sandy_project_ref":"zmqlyygzqoidkcwdysok"}'',''sha256''),''hex'')
  OR NOT EXISTS(SELECT 1 FROM public.sandy_provider_read_admission_proofs proof WHERE proof.admission_id=admission.id
   AND proof.actor_id=admission.actor_id AND proof.credential_id IS NOT DISTINCT FROM admission.credential_id
   AND proof.request_id=admission.request_id AND proof.grant_id=admission.grant_id AND proof.operation=admission.operation
   AND proof.input_sha256=admission.input_sha256 AND proof.scope_sha256=admission.scope_sha256
   AND proof.registry_revision_sha256=admission.registry_revision_sha256)) THEN RAISE EXCEPTION ''consumer_scoped_admission_required''; END IF;
 expected_consumer:=CASE WHEN p_operation LIKE ''supabase.%'' THEN ''supabase_management'' WHEN p_operation LIKE ''github.%'' THEN ''github_api'' WHEN p_operation LIKE ''gcp.%'' THEN ''gcp_access_token'' END;
 IF entry.handler=''sandy-credential-lifecycle-api'' THEN
  SELECT * INTO operation_target FROM public.sandy_credential_targets WHERE scope_sha256=admission.scope_sha256 AND enabled AND verified LIMIT 1;
  expected_consumer:=CASE operation_target.provider WHEN ''supabase_edge_secret'' THEN ''supabase_management'' WHEN ''github_actions_secret'' THEN ''github_api'' WHEN ''gcp_secret'' THEN ''gcp_access_token'' WHEN ''gcp_service_account_key'' THEN ''gcp_access_token'' END;
 END IF;
 IF expected_consumer IS DISTINCT FROM p_consumer THEN RAISE EXCEPTION ''consumer_provider_scope_mismatch''; END IF;
 SELECT * INTO binding FROM public.sandy_credential_consumer_bindings WHERE consumer=p_consumer FOR SHARE;
 IF binding.consumer IS NULL THEN RETURN jsonb_build_object(''ok'',true,''source'',''existing_configuration'',''active_version_id'',NULL); END IF;
 SELECT * INTO target FROM public.sandy_credential_targets WHERE id=binding.target_id FOR SHARE;
 IF target.id IS NULL THEN RAISE EXCEPTION ''consumer_configured_target_missing''; END IF;
 IF target.active_version_id IS NULL THEN
  IF EXISTS(SELECT 1 FROM public.sandy_credential_consumer_access WHERE target_id=target.id)
  OR EXISTS(SELECT 1 FROM public.sandy_credential_rotations WHERE target_id=target.id AND state=''activated'') THEN RAISE EXCEPTION ''consumer_active_pointer_removed''; END IF;
  RETURN jsonb_build_object(''ok'',true,''source'',''existing_configuration'',''active_version_id'',NULL);
 END IF;
 IF NOT binding.enabled OR NOT binding.verified OR NOT target.enabled OR NOT target.verified OR target.config_sha256 IS DISTINCT FROM binding.target_config_sha256
 OR NOT public.sandy_credential_consumer_target_matches(p_consumer,target) THEN RAISE EXCEPTION ''consumer_active_binding_refused''; END IF;
 SELECT * INTO version FROM public.sandy_credential_versions WHERE id=target.active_version_id AND target_id=target.id FOR SHARE;
 IF version.id IS NULL OR version.state IS DISTINCT FROM ''active'' THEN RAISE EXCEPTION ''consumer_active_version_refused''; END IF;
 -- Active versions must retain the prior custody proof, including a real
 -- successful verification admission with a digest-bound observation.
 IF NOT EXISTS(SELECT 1 FROM public.sandy_credential_rotations rotation JOIN public.sandy_api_execution_admissions proof ON proof.id=rotation.verification_admission_id
  WHERE rotation.target_id=target.id AND rotation.staged_version_id=version.id AND rotation.state=''activated''
  AND rotation.target_config_sha256=target.config_sha256 AND proof.operation=''system.credentials.provider.verify'' AND proof.state=''succeeded''
  AND proof.actor_id=rotation.actor_id AND proof.credential_id IS NULL AND proof.approval_id IS NOT NULL AND proof.scope_sha256=target.scope_sha256
  AND proof.result_sha256=encode(extensions.digest(rotation.verification_canonical,''sha256''),''hex'')
  AND rotation.verification_canonical::jsonb=rotation.verification_evidence
  AND rotation.verification_evidence->>''rotation_id''=rotation.id::text AND rotation.verification_evidence->>''target_id''=target.id::text
  AND rotation.verification_evidence->>''target_config_sha256''=target.config_sha256
  AND rotation.verification_evidence->>''provider_verified''=''true'' AND rotation.verification_evidence->>''material_sha256''=version.material_sha256) THEN RAISE EXCEPTION ''consumer_active_readback_required''; END IF;
 SELECT * INTO previous FROM public.sandy_credential_consumer_access WHERE admission_id=p_admission AND consumer=p_consumer;
 IF previous.admission_id IS NOT NULL AND (previous.actor_id IS DISTINCT FROM p_actor OR previous.target_id IS DISTINCT FROM target.id OR previous.version_id IS DISTINCT FROM version.id OR previous.material_sha256 IS DISTINCT FROM version.material_sha256) THEN RAISE EXCEPTION ''consumer_pointer_changed_during_execution''; END IF;
 SELECT decrypted_secret INTO material FROM vault.decrypted_secrets WHERE id=version.vault_secret_id;
 IF material IS NULL OR octet_length(material) NOT BETWEEN 1 AND 65536 OR encode(extensions.digest(material,''sha256''),''hex'') IS DISTINCT FROM version.material_sha256 THEN RAISE EXCEPTION ''consumer_material_integrity_failed''; END IF;
 INSERT INTO public.sandy_credential_consumer_access(admission_id,consumer,actor_id,target_id,version_id,material_sha256)
 VALUES(p_admission,p_consumer,p_actor,target.id,version.id,version.material_sha256) ON CONFLICT DO NOTHING;
 IF previous.admission_id IS NULL THEN PERFORM public.sandy_api_append_audit(p_actor,p_operation,admission.request_id,admission.credential_id,p_admission,''credential_consumer'',''resolved'',admission.input_sha256,
  encode(extensions.digest(jsonb_build_object(''consumer'',p_consumer,''target_id'',target.id,''version_id'',version.id,''material_sha256'',version.material_sha256)::text,''sha256''),''hex'')); END IF;
 target_document:=jsonb_build_object(''id'',target.id,''provider'',target.provider,''resource'',target.resource,''enabled'',target.enabled,''verified'',target.verified,''active_version_id'',target.active_version_id,''scope_sha256'',target.scope_sha256,''config_sha256'',target.config_sha256);
 RETURN jsonb_build_object(''ok'',true,''source'',''vault_active'',''consumer'',p_consumer,''admission_id'',p_admission,''active_version_id'',version.id,''target'',target_document,''value'',material,''material_sha256'',version.material_sha256,''provider_version_id'',version.provider_version_id);
END ';
REVOKE ALL ON FUNCTION public.sandy_provider_supplement_context(jsonb) FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON FUNCTION public.sandy_credential_resolve_consumer(text,uuid,uuid,text) FROM PUBLIC,anon,authenticated;
